<?php

declare(strict_types=1);

namespace PhpGtk4\Tests;

use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

/**
 * docs/INVENTORY.md is generated by gen/gir.php --install from the GIR files and the hand-written
 * stub, and the `gen` stage keeps it in step with those inputs. This holds it to the other side:
 * the classes the built module actually registers. A class registered by hand in MINIT without a
 * stub declaration, or a row whose class no longer exists, shows up here and nowhere else.
 */
final class InventoryTest extends TestCase
{
    private const FILE = __DIR__ . '/../docs/INVENTORY.md';

    /** @return list<string> the classes the table lists, short names */
    private static function listed(): array
    {
        $md = (string) file_get_contents(self::FILE);
        preg_match_all('/^\| `([A-Za-z0-9_]+)` \| /m', $md, $m);

        return $m[1];
    }

    /** @return list<string> */
    private static function registered(): array
    {
        $names = [];
        foreach (new \ReflectionExtension('gtk4')->getClasses() as $class) {
            $names[] = substr($class->getName(), strlen('Gtk4\\'));
        }
        sort($names, SORT_STRING);

        return $names;
    }

    public function testEveryRegisteredClassIsListedOnceAndNothingElse(): void
    {
        $listed = self::listed();
        self::assertSame(array_values(array_unique($listed)), $listed, 'a class is listed twice');
        // The inventory always carries the conditional namespaces (the generator runs with their
        // GIR whether or not the build has the feature); a build without them has no such classes.
        $available = array_values(array_filter($listed, Features::available(...)));
        sort($available, SORT_STRING);
        self::assertSame(self::registered(), $available, 'docs/INVENTORY.md and the registered classes differ');
    }

    /** @return iterable<string, array{string}> */
    public static function rows(): iterable
    {
        $md = (string) file_get_contents(self::FILE);
        foreach (explode("\n", $md) as $line) {
            if (preg_match('/^\| `([A-Za-z0-9_]+)` \| /', $line, $m) === 1) {
                yield $m[1] => [$line];
            }
        }
    }

    #[DataProvider('rows')]
    public function testEveryRowLinksItsDocumentation(string $row): void
    {
        self::assertMatchesRegularExpression(
            '#\| \[[^\]]+\]\((https://[^)\s]+|[A-Z-]+\.md)\)#',
            $row,
            'a row links a documentation page (https://...) or a document in docs/',
        );
    }
}
